<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; try { if(!is_dir(storage_path("api-docs"))) mkdir(storage_path("api-docs"),0777,true); $gen = new \OpenApi\Generator(new \Psr\Log\NullLogger()); $finder = new \OpenApi\SourceFinder([__DIR__."/app"],[],"*.php"); $openapi = $gen->generate($finder); $json = $openapi->toJson(); file_put_contents(storage_path("api-docs/api-docs.json"), $json); $data = json_decode($json, true); echo "Paths: ".count($data["paths"] ?? [])."\n"; echo "Schemas: ".count($data["components"]["schemas"] ?? [])."\n"; echo "Tags: ".count($data["tags"] ?? [])."\n"; foreach(array_keys($data["paths"] ?? []) as $p) echo "  $p\n"; } catch(\Throwable $e) { echo "ERR: ".$e->getMessage()."\n".$e->getFile().":".$e->getLine()."\n"; }
